    const showOnlineStatus = settings?.show_online_status !== false

    // ✅ Only show phone if allowed
    const phoneDisplay = showPhone && profile?.phone ? (
        <span className="text-gray-600 flex items-center gap-1"><Phone size={14} /> {profile.phone}</span>
    ) : null

    // ✅ Only show online status if allowed
    const onlineStatus = showOnlineStatus ? (
        <span className="text-xs text-green-500 flex items-center gap-1">
            <span className="w-2 h-2 bg-green-500 rounded-full" /> Online
        </span>
    ) : null
}
